// GitHub KPI row (#402) — a 6-up KPI stat grid: commits, PRs merged, net lines, CI pass rate, review
// latency, contributors. Extracted from GitHubPulse's inline card into its own composable record;
// adds the loading state the inline version didn't have.
import { StatCard, fmt } from "@/shared/ui/charts";
import { Box } from "@/shared/ui/layout/Box";

export type StatTone = "fg" | "accent" | "info" | "success" | "danger";
export interface PulseKpis { commitsWeek: number; prsMerged: number; netLines: number; passRate: number; reviewLatencyH: number; contributors: number; botShare: number }

const DEMO_KPIS: PulseKpis = { commitsWeek: 38, prsMerged: 9, netLines: 1240, passRate: 92, reviewLatencyH: 5, contributors: 4, botShare: 12 };

export function KpiRow({ kpis = DEMO_KPIS, runs = 48, loading = false }: { kpis?: PulseKpis; runs?: number; loading?: boolean }) {
  const cards: Array<{ k: string; v: string; sub: string; tone?: StatTone }> = [
    { k: "commits · 7d", v: String(kpis.commitsWeek), sub: "on the default branch", tone: "fg" },
    { k: "PRs merged · 7d", v: String(kpis.prsMerged), sub: "merged pull requests", tone: "accent" },
    { k: "net lines · 7d", v: `${kpis.netLines >= 0 ? "+" : ""}${fmt(kpis.netLines)}`, sub: "added minus removed", tone: kpis.netLines >= 0 ? "success" : "danger" },
    { k: "CI pass rate", v: `${kpis.passRate}%`, sub: `${runs} runs`, tone: kpis.passRate >= 90 ? "success" : "fg" },
    { k: "review latency", v: kpis.reviewLatencyH ? `${kpis.reviewLatencyH}h` : "-", sub: "open to merge median", tone: "fg" },
    { k: "contributors", v: String(kpis.contributors), sub: `${kpis.botShare}% bot commits`, tone: "info" },
  ];
  return (
    <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))", gap: 10 }}>
      {cards.map((c) => <StatCard key={c.k} {...c} loading={loading} />)}
    </Box>
  );
}
